from dsl import *
o="외전당가"
story("서장_외전당가",o,1,"서른여섯 대의 침",
 "쌍둥이 동생 소완이 쓰러진 지 사흘째다. 입술은 재처럼 식었는데 맥은 뛴다. 가주 만독수 당천기가 침 서른여섯 대를 꽂고 손을 씻었다. \"당가의 독이 아니다. 나도 이름을 모른다. 이 침은 십 년을 버틴다. 십 년 안에 약을 못 찾으면 침을 뽑는 날이 제삿날이다.\" 가주는 나를 보지 않고 덧붙였다. \"가문은 독 하나에 사람을 다 풀 수 없다. 갈 사람은 너뿐이다, 〈이름:아/야〉.\"",
 [C("동생의 머리맡에 약속하고 떠난다",O("소완의 손은 차가웠다. 그 손목에 내 암기 주머니의 끈을 묶어 두었다. 돌아와서 풀 것이다.",alignment=AL(j=20),stats={"mind":1})),
  C("독고에서 쓸 만한 것부터 챙긴다",O("독고지기가 눈을 감아 주었다. 남의 독을 풀러 가는 길에 내 독이 없을 수는 없다.",alignment=AL(s=20),silver=15,item="해독단")),
  C("누가 독을 먹였는지부터 캔다",O("동생의 찻잔, 향낭, 침방을 사흘 동안 뒤졌다. 찾은 것은 낯선 벌레 허물 하나였다. 가문 안에 손이 있다.",alignment=AL(m=20),stats={"martial":1}))])
story("외전당가_2",o,25,"약왕곡의 줄",
 "두 해 동안 독경을 뒤지고 의원을 찾아다녔다. 남은 곳은 약왕곡뿐이다. 곡 어귀에 환자들이 줄을 섰고, 곡주는 몇 해째 자리에 없다고 한다. 약 가마 앞의 대제자가 동생의 맥과 증세를 적은 종이를 오래 들여다본다. \"남만의 고독에 북쪽의 한독을 섞었소. 이런 걸 빚을 손은 천하에 몇 없지. 풀려면 셋이 있어야 하오. 남쪽 금섬의 독주머니, 북쪽 빙잠의 실, 그리고 이 독을 빚은 자의 처방.\" 그가 붓을 든다. \"약재 다루는 법은 적어 드리지. 다만 보다시피 줄이 길어서.\"",
 [C("줄 선 환자들의 약을 함께 달이며 기다린다",O("열흘을 가마 앞에서 보냈다. 독을 다루던 손이 약을 다루는 법을 배웠다. 대제자가 글 끝에 한 줄을 더 적어 주었다. '독과 약은 한 뿌리다.'",alignment=AL(j=60),stats={"mind":4,"internal":3},fame=10,flags=["당가_처방"])),
  C("은자를 얹어 차례를 산다",O("전낭이 가벼워진 만큼 줄이 짧아졌다. 글은 반나절 만에 나왔다. 줄에 선 사람들의 눈은 보지 않았다.",alignment=AL(s=40),silver=-60,stats={"martial":4},flags=["당가_처방"]),req={"min_silver":60}),
  C("침 한 대를 가마 위에 꽂아 보이고 먼저 받아 낸다",O("가마 뚜껑에 박힌 침이 파르르 떨었다. 대제자의 붓이 빨라졌다. 곡을 나설 때 등 뒤에서 누가 침을 뱉었다.",alignment=AL(m=60),stats={"external":3,"martial":2},flags=["당가_처방"]))])
story("외전당가_3",o,49,"묘강의 장터",
 "금섬은 남만의 늪에 산다. 묘강의 장터에서는 야수궁의 술사들과 오독문의 독꾼들이 독충을 근으로 달아 판다. 좌판마다 뚜껑 덮은 항아리가 꿈틀거린다. 금섬의 독주머니를 가진 사람은 하나뿐이다. 오독문의 독꾼 흑지주 마랑이 손톱으로 항아리를 두드린다. \"당가 사람이 여기까지 독을 사러 오다니. 값은 솜씨로 받지. 내 독을 받아 내면 주머니는 네 것이다.\"",
 [C("독 겨룸을 받는다",O("마랑이 제 손등에 번진 반점을 내려다보다 웃었다. \"풀 줄도 아는구나.\" 항아리가 내 쪽으로 밀려왔다. 그가 낮게 덧붙였다. \"네가 찾는 독은 우리 문 안에서 나온 것이 맞다. 다만 빚은 손은 남만 사람이 아니야. 너희 쪽 글씨다.\"",battle="독문고수",spar=True,foe="흑지주 마랑",foe_line="\"사천의 독이 남만의 늪에서도 통하는지 보자.\"",lose_next="빈손",alignment=AL(j=40),stats={"martial":5,"mind":3},mastery=12,flags=["당가_금섬"])),
  C("은자로 산다",O("마랑이 은자를 이로 깨물어 보고 항아리를 내주었다. \"당가가 돈을 다 쓰네. 급하긴 급한 모양이야.\"",alignment=AL(s=40),silver=-120,stats={"mind":3},flags=["당가_금섬"]),req={"min_silver":120}),
  C("밤에 좌판을 턴다",O("항아리를 안고 늪을 건넜다. 이튿날 장터에는 당가 사람을 보면 문을 닫으라는 말이 돌았다.",alignment=AL(m=60),stats={"external":4,"martial":3},flags=["당가_금섬"])),
  C("빈손으로 돌아선다",O("금섬의 독주머니 없이 약을 빚으려면 다른 것으로 메워야 한다. 약재를 적은 글의 한 줄에 줄을 그었다.",stats={"mind":2},flags=["당가_모자람"]))],
 parts={"빈손":part("마랑의 독이 손끝에서 팔꿈치까지 올라왔다. 해독단을 씹으며 물러났다. 주머니는 여전히 그의 좌판에 있다.",
   [C("남은 은자를 털어 산다",O("마랑이 어깨를 으쓱했다. \"진 놈한테는 값을 더 받는다.\"",silver=-150,flags=["당가_금섬"]),req={"min_silver":150}),
    C("빈손으로 돌아선다",O("약재를 적은 글의 한 줄에 줄을 그었다. 다른 것으로 메워야 한다.",flags=["당가_모자람"]))])})
story("외전당가_4",o,73,"북해의 실",
 "빙잠은 북해의 얼음굴에서만 실을 낸다. 천 리 빙원 끝에서 흰 옷의 순찰이 길을 막았다. 북해빙궁이다. \"남쪽은 불타고 있다 들었다. 불을 피해 온 자는 아닌 듯한데.\" 사정을 말하자 순찰대주가 한참 나를 본다. \"빙잠은 궁의 것이다. 죽이지 않고 실만 얻는 법이 있다. 손이 얼어 떨어질 각오면.\"",
 [C("궁의 법대로 맨손을 얼음굴에 넣는다",
    O("내력으로 손을 감싸고 팔꿈치까지 밀어 넣었다. 빙잠이 손등을 기어오르며 실을 감았다. 손톱 둘이 빠졌지만 실은 온전하다. 순찰대주가 길을 열어 주었다.",req={"stat_min":{"internal":600}},alignment=AL(j=60),stats={"internal":6,"mind":4},flags=["당가_빙잠"]),
    O("손이 먼저 얼었다. 순찰대주가 내 팔을 끌어냈다. 실은 반 타래뿐이고 손가락은 한 달을 굽히지 못했다. 그래도 빈손은 아니다.",req={"stat_max":{"internal":599}},alignment=AL(j=60),stats={"internal":4},hp_pct=-25,flags=["당가_빙잠"])),
  C("순찰을 꺾고 굴에 든다",O("순찰대주가 무릎을 꿇은 사이 굴에서 실 한 타래를 걷었다. 빙궁은 이 일을 잊지 않을 것이다.",battle="북해고수",foe="빙궁 순찰대주 상한",foe_line="\"궁의 것에 손을 대는 자는 얼음 밑에 묻는다.\"",alignment=AL(s=50),stats={"external":5,"martial":4},flags=["당가_빙잠"])),
  C("빙잠을 죽여 통째로 가져간다",O("얼음굴이 무너지는 소리를 등지고 달렸다. 실은 넉넉하다. 북해의 바람이 사흘을 따라왔다.",alignment=AL(m=80),stats={"external":4,"internal":4},flags=["당가_빙잠"])),
  C("돌아선다",O("빙원을 되짚어 나왔다. 약재를 적은 글에 줄이 하나 더 그어졌다.",stats={"mind":2},flags=["당가_모자람"]))])
story("외전당가_5",o,97,"가문의 서고",
 "여덟 해 만에 사천으로 돌아왔다. 남은 것은 독을 빚은 자의 처방이다. 서고지기 노인이 먼지 앉은 족보를 펴 보인다. 삼십 년 전 파문된 이름 하나. 당가의 독경 하권을 들고 남만으로 내려간 방계의 여인이다. 지금은 오독문의 주인, 천주독모 섭홍이라 불린다. 노인이 낮게 말한다. \"가주께서도 아신다. 가문의 독경으로 빚은 독이니 가문의 수치지. 그래서 아무도 보내지 못한 게야. 너 말고는.\"",
 [C("가주에게 따져 묻는다",O("가주는 침통을 닦던 손을 멈추지 않았다. \"알았다. 알았기에 십 년짜리 침을 놓았다. 네가 강해질 시간이었다.\" 그가 내 손에 가주의 패를 쥐여 주었다. \"가문의 이름으로 가거라.\"",alignment=AL(j=60),stats={"mind":6,"martial":4},full_growth=True,flags=["당가_가주패"])),
  C("서고에서 독경 상권을 베껴 간다",O("하권을 상대하려면 상권을 알아야 한다. 사흘 밤을 베꼈다. 서고지기는 등불 심지만 갈아 주었다.",alignment=AL(s=60),stats={"martial":8},mastery=15,full_growth=True,flags=["당가_상권"])),
  C("동생의 찻잔에 독을 넣은 손부터 찾는다",O("침방지기는 끝내 불었다. 독모가 있는 곳은 남만 천주동. 동생이 골라진 까닭도. 섭홍은 가주의 핏줄이 쓰러지는 것을 보고 싶어 했다.",battle="당가배신자",foe="침방지기 당목",foe_line="\"아가씨 찻잔에 넣은 건 한 방울이었소. 한 방울 값으로 논 열 마지기를 받았지.\"",alignment=AL(m=60),stats={"external":5,"martial":5},full_growth=True,flags=["당가_내통"]))])
story("외전당가_끝",o,120,"천주동",
 "남만 천주동. 거미줄 같은 흰 실이 동굴 천장을 덮었다. 그 아래에서 오독문주 천주독모 섭홍이 차를 달인다. 얼굴이 가주를 닮았다. \"십 년 걸렸구나. 네 동생에게 쓴 독은 내가 당가에 보내는 편지였다. 독경 하권이 상권보다 낫다는 편지. 답장으로 가주가 아니라 네가 왔고.\" 그녀가 찻잔 옆에 종이 한 장을 놓는다. 처방이다. \"가져가려면 나를 넘어야지. 당가의 방식으로.\"",
 [C("당가의 이름으로 독모를 넘는다",O("섭홍이 흰 실 위로 주저앉았다. \"상권도... 쓸 만하구나.\" 처방은 찻잔 옆에 그대로 있다.",battle="외전_오독문주",next="약")),
  C("처방 값으로 베껴 온 독경 상권을 내민다",O("섭홍이 상권을 넘겨 보다 웃었다. \"삼십 년 만에 짝을 맞추는구나.\" 처방이 내 쪽으로 밀려왔다. 당가의 독경 두 권이 이제 남만에 있다.",alignment=AL(s=80),flags=["당가_독경넘김"],next="약"),req={"flag":"당가_상권"},hidden=True),
  C("동생의 독을 내 몸으로 옮기는 법을 묻는다",O("섭홍이 처음으로 찻잔을 내려놓았다.",next="대신"))],
 parts={
  "약":part("처방과 약재를 안고 사천으로 달렸다. 침이 버티는 마지막 달이다. 동생의 방에 약탕기를 걸었다.",
   [C("약재를 모두 넣어 해독단을 빚는다",O("약탕기가 사흘을 끓었다.",ending="외전당가_해독"),req={"not_flag":"당가_모자람"},hidden=True),
    C("모자란 약재를 다른 것으로 메워 빚는다",O("약탕기가 사흘을 끓었다. 빛깔이 처방과 조금 달랐다.",ending="외전당가_반쪽"),req={"flag":"당가_모자람"},hidden=True),
    C("모자란 만큼의 독을 내 몸으로 받아 낸다",O("약 반 첩을 동생에게 먹이고, 남은 독은 침으로 내 팔에 옮겼다.",ending="외전당가_대신"),req={"flag":"당가_모자람"},hidden=True)]),
  "대신":part("\"그 법은 있다. 피붙이라면 독이 옮겨 간다. 받은 쪽은 무공도 입맛도 잃고 십 년쯤 더 산다.\" 섭홍이 침 한 대를 내민다. \"당가 사람이 이런 걸 묻다니. 가주가 너를 잘못 길렀구나. 아니면 잘 길렀거나.\"",
   [C("침을 받아 사천으로 돌아간다",O("침 한 대가 품에서 무거웠다.",ending="외전당가_대신")),
    C("침을 내려놓고 독모를 넘는다",O("섭홍이 흰 실 위로 주저앉았다. \"그래, 그게 당가지.\" 처방은 찻잔 옆에 그대로 있다.",battle="외전_오독문주",next="약"))])})
enemy("외전_오독문주","십대고수",hp=22000,attack=245,armor=24,name="천주독모 섭홍",title="오독문주",desc="삼십 년 전 당가의 독경 하권을 들고 남만으로 내려간 방계의 여인. 오독문을 손에 넣고 당가도 모르는 독을 빚었다.",
 intro="\"상권만 읽은 손이 하권을 이길 수 있는지 보자.\"",outro="섭홍이 흰 실 위로 쓰러졌다. \"삼십 년을 기다린 답장이... 이거였구나.\"",
 specials=[{"name":"천주만화","every":3,"mult":2.1,"poison":{"damage":18,"rounds":3}},{"name":"본명고","every":5,"mult":1.4,"qi_drain":15}],
 phases=[{"hp_pct":45,"attack_mult":1.2,"text":"섭홍이 소매를 걷자 팔뚝의 검은 무늬가 살아 움직인다. \"하권의 마지막 장은 내 몸에 적었다.\"","quirks":[{"type":"sever","percent":25,"name":"무음독"}]}])
ending("외전당가_해독",o,"풀린 독","해독",10,"〈성명:은/는〉 십 년 만에 동생의 침을 뽑았다. 당가도 이름을 몰랐던 독이 풀렸다.",[
 F(({}, "동생 소완은 사흘 뒤 눈을 떴다. 첫마디는 \"배고파\"였다.")),
 F(({"flag":"당가_가주패"},"가주는 침 서른여섯 대를 제 손으로 거두었다. 아무 말도 하지 않았지만 그날 저녁 가주의 상에 〈그〉의 자리가 놓였다."),({"flag":"당가_독경넘김"},"당가의 독경 두 권이 남만에 있다는 것을 가문은 오래 몰랐다. 〈그〉만 알았다."),({"flag":"당가_내통"},"침방지기의 논 열 마지기는 가문이 거두어 약재밭으로 갈았다."),({}, "가주는 침 서른여섯 대를 거두며 한마디만 했다. \"늦지는 않았구나.\"")),
 F(({"dominant":"정도"},"사천의 약방들은 그 뒤로 당가를 독의 집안이 아니라 약의 집안이라고도 불렀다."),({"dominant":"마도"},"남만의 장터에서는 지금도 당가 사람을 보면 항아리 뚜껑부터 덮는다."),({}, "새 해독단의 이름은 동생이 지었다. 소완단이다.")),
 F(({}, "〈그〉는 약재를 적은 글 끝에 약왕곡의 한 줄을 옮겨 적어 서고에 넣었다. '독과 약은 한 뿌리다.'"))])
ending("외전당가_반쪽",o,"반쪽의 약","반약",6,"〈성명:은/는〉 동생을 살렸다. 다만 약이 모자랐다.",[
 F(({}, "소완은 눈을 떴지만 왼손이 다시는 침을 쥐지 못했다. 당가의 딸에게는 작지 않은 일이다.")),
 F(({}, "동생은 원망하지 않았다. 〈그〉는 그것이 더 견디기 어려웠다.")),
 F(({}, "모자랐던 약재의 이름은 〈그〉의 침통 안쪽에 지금도 새겨져 있다."))])
ending("외전당가_대신",o,"옮겨 받은 독","대신",8,"〈성명:은/는〉 동생의 독을 제 몸으로 옮겨 받았다. 동생은 일어났고 〈그〉는 침통을 내려놓았다.",[
 F(({}, "소완은 눈을 뜨자마자 제 쌍둥이의 팔에 꽂힌 침부터 보았다. 한참을 울었다.")),
 F(({}, "〈그〉는 무공을 잃었다. 맛도 잃었다. 동생이 달인 차가 쓴지 단지 알지 못한 채 십 년을 더 마셨다.")),
 F(({"flag":"당가_가주패"},"가주는 〈그〉의 이름을 가문의 독경 상권 맨 앞장에 적었다. 독으로 이름을 올린 것이 아닌 첫 사람이다."),({}, "당가의 아이들은 지금도 침을 처음 쥐는 날 그 이야기를 듣는다."))])
rnd("당가_누명",[1,2],"독 먹은 표사",
 "객잔 마루에 표사 하나가 거품을 물고 쓰러졌다. 누군가 내 허리의 암기 주머니를 가리킨다. \"사천 사람이다. 독이라면 당가지.\" 탁자들이 일제히 뒤로 밀린다.",
 [C("말없이 맥부터 짚고 해독한다",O("독은 상한 복어였다. 침 세 대로 토하게 했다. 표사가 숨을 돌리자 객잔 주인이 술을 내왔다. 가리키던 손가락은 어느새 보이지 않았다.",alignment=AL(j=40),stats={"mind":4},fame=15)),
  C("해독해 주고 값을 받는다",O("표두가 전낭을 풀었다. 당가의 침은 싸지 않다.",alignment=AL(s=30),silver=60,stats={"martial":2})),
  C("가리킨 자의 잔에 침을 떨어뜨려 보인다",O("잔 속의 술이 푸르게 변했다. 물론 색만 변하는 가루다. 객잔이 조용해졌다. 표사는 그사이 제풀에 토하고 살아났다.",alignment=AL(m=40),stats={"external":2,"martial":3}))],origin=o)
rnd("당가_전서",[3,4],"가문에서 온 침통",
 "전서구가 사천에서 날아왔다. 대통 안에 가는 침 다섯 대와 쪽지가 들어 있다. 동생의 글씨다. 가주의 침이 맥을 붙든 뒤로 동생은 열흘에 한 번쯤 반나절 눈을 뜬다고 한다. 그 반나절에 쓴 글씨라 삐뚤빼뚤하다. '침방 서랍 밑에 내가 익히던 것이 있어. 어차피 나는 못 쓰니까 네가 써.' 쪽지 뒤에 구결이 빽빽하다.",
 [C("구결을 익힌다",O("동생이 몰래 다듬던 오독침이다. 침 다섯 대를 손가락 사이에 끼워 보았다. 동생의 손 크기에 맞춘 침이라 조금 짧다.",skill="오독침",stats={"martial":4})),
  C("답장부터 쓴다",O("약재가 얼마나 모였는지, 남쪽 늪이 얼마나 더운지 적었다. 구결은 그다음에 폈다. 동생이 몰래 다듬던 오독침이다.",skill="오독침",stats={"mind":4}))],origin=o,req={"no_skill":"오독침","sect":"당가"})

o="외전빙궁"
story("서장_외전빙궁",o,1,"얼음의 문",
 "북해빙궁의 얼음 문이 등 뒤에서 닫혔다. 궁주 빙백검후 설란은 배웅하지 않았다. 떠나기 전날 밤 한마디만 했다. \"남쪽에 백 년 전의 불이 다시 붙는다 한다. 궁은 백 년 전에도 문을 닫고 살아남았다. 이번에도 그래야 하는지 나는 모르겠다. 네가 십 년을 보고 와서 답해라. 열 것인가, 닫을 것인가.\" 소궁주 하란이 문틈으로 털옷 한 벌을 던져 주었다. \"얼어 죽지는 마라. 답은 들어야 하니까.\"",
 [C("본 것을 빠짐없이 적겠다고 다짐한다",O("빈 책 한 권을 품에 넣었다. 첫 장에 날짜를 적었다.",alignment=AL(j=20),stats={"mind":1})),
  C("궁에 이로운 것만 골라 보겠다",O("남쪽에서 궁이 살 것과 팔 것. 책의 첫 장을 둘로 갈랐다.",alignment=AL(s=20),stats={"martial":1})),
  C("남쪽이 얼마나 약한지부터 재 보겠다",O("첫 장에 적었다. '남쪽 무인 하나를 꺾는 데 몇 수가 드는가.'",alignment=AL(m=20),stats={"external":1}))])
story("외전빙궁_2",o,25,"저울을 든 사절",
 "낙양에 궁의 사절단이 들었다. 나는 말석에 앉아 적는다. 객잔 아래층에서는 무림맹의 젊은 호법과 사도련의 책사, 붉은 옷의 여인이 이름난 무인들에게 차례로 잔을 권한다. 다들 같은 말을 한다. 곧 큰일이 난다고. 사절 대표가 찻잔 너머로 묻는다. \"〈이름:아/야〉, 너는 두 해를 먼저 보았다. 셋 가운데 어느 쪽이 십 년 뒤에도 남아 있겠느냐. 궁주께 올릴 첫 글이다.\"",
 [C("무림맹이라 적는다. 지킬 것이 있는 쪽이 오래 간다",O("사절 대표가 글을 읽고 접었다. \"지킬 것이 많으면 잃을 것도 많다. 어쨌든 적어 두마.\"",alignment=AL(j=60),stats={"mind":4,"internal":3},fame=10,flags=["빙궁_맹"])),
  C("사도련이라 적는다. 값을 아는 쪽은 망하지 않는다",O("그날 밤 사도련의 책사가 어떻게 알았는지 내 방에 전낭을 두고 갔다. 글 값이라 했다.",alignment=AL(s=60),stats={"martial":4},silver=60,flags=["빙궁_련"])),
  C("신교라 적는다. 가장 센 쪽이 남는다",O("붉은 옷의 여인이 계단에서 나를 스쳐 지나며 웃었다. 글을 본 것도 아닌데.",alignment=AL(m=60),stats={"external":4,"internal":3},flags=["빙궁_교"])),
  C("아직 모른다고 적는다",O("사절 대표가 처음으로 웃었다. \"그게 제일 쓰기 어려운 글이다.\"",stats={"mind":6},flags=["빙궁_모름"]))])
story("외전빙궁_3",o,49,"만년설의 찻자리",
 "곤륜 장문인 설봉자가 궁의 사절과 단둘이 찻자리를 가졌다. 나는 문밖에서 눈을 맞으며 섰다. 반나절 뒤 사절이 나와 봉한 글 하나를 건넨다. \"곤륜은 싸움이 기울면 어린 제자들을 북해로 피신시키고 싶어 한다. 궁이 문을 열어 준다면. 낙양에는 벌써 곤륜이 발을 뺀다는 소문이 돈다. 이 글을 그대로 올릴지, 네가 본 대로 고쳐 올릴지는 네 붓에 달렸다.\" 그때 산문 아래에서 맹의 순찰조가 올라온다. 밀약의 증거를 찾는 눈이다.",
 [C("순찰조에게 있는 그대로 말한다",O("\"피신이지 내통이 아니오.\" 순찰조장은 한참 눈을 맞다가 돌아섰다. 며칠 뒤 낙양의 소문이 조금 잦아들었다. 사절은 혀를 찼지만 글은 고치지 않았다.",alignment=AL(j=60),stats={"mind":5,"internal":3},fame=15,flags=["빙궁_곤륜"])),
  C("글을 품고 순찰조를 물린다",O("순찰조가 물러난 눈밭에서 봉한 글은 온전했다. 궁의 일은 궁만 안다.",battle="맹순찰조",spar=True,foe="맹 순찰조장 유검 방초",foe_line="\"북해 사람이 곤륜에서 무얼 들고 나오나. 품을 보자.\"",alignment=AL(s=40),stats={"martial":5,"external":3},mastery=10,flags=["빙궁_밀약"])),
  C("글을 고쳐 쓴다. 곤륜이 궁에 빚을 지도록",O("붓 끝으로 몇 자를 바꿨다. 피신은 귀순이 되었다. 설봉자는 이 글을 영영 보지 못할 것이다.",alignment=AL(m=50),stats={"mind":4,"martial":3},flags=["빙궁_밀약"]))])
story("외전빙궁_4",o,73,"불타는 낙양",
 "정마대전이 터졌다. 낙양이 불탄다. 궁의 사절단은 짐을 싸서 북문으로 빠진다. 궁의 법은 하나다. 어느 편에도 서지 않는다. 북문 앞에 피난민이 몰렸고 그 뒤를 신교의 선봉이 쫓는다. 사절 대표가 내 소매를 잡는다. \"보는 것까지가 우리 일이다.\"",
 [C("법을 어기고 북문 앞에 선다",O("피난민이 다 빠져나갈 때까지 문 앞에 섰다. 흰 옷이 붉게 젖었다. 사절 대표는 그날 일을 한 줄도 적지 않았다. 적지 않는 것이 그가 해 줄 수 있는 전부였다.",battle="호교대",foe="신교 선봉 흑기대",foe_line="\"흰 옷은 비켜라. 북해는 이 싸움에 없다 들었다.\"",alignment=AL(j=90),stats={"external":6,"internal":5},fame=30,flags=["빙궁_북문"])),
  C("법대로 문루에서 지켜보고 적는다",O("끝까지 보았다. 누가 먼저 달아났고 누가 끝까지 남았는지. 붓이 세 번 멈췄다.",stats={"mind":8,"internal":4},flags=["빙궁_방관"])),
  C("불타는 상단 창고에서 궁에 쓸 것을 챙긴다",O("타다 남은 비단과 약재를 수레 둘에 실었다. 주인은 이미 달아났거나 죽었다. 궁의 겨울은 길다.",alignment=AL(s=70),silver=150,stats={"martial":4},flags=["빙궁_방관"])),
  C("신교 선봉의 솜씨를 가까이서 잰다",O("선봉장의 뒤를 반나절 밟았다. 저들이 사람을 어떻게 베는지 적었다. 궁이 문을 닫는다면 이 글이 쓸모 있을 것이다.",alignment=AL(m=60),stats={"external":5,"martial":5},flags=["빙궁_방관"]))])
story("외전빙궁_5",o,97,"소궁주의 마중",
 "여덟 해가 지났다. 소궁주 설령수 하란이 몸소 빙원을 건너왔다. 주막 평상에 앉아 내가 적은 책을 넘긴다. 여덟 권이다. \"궁주께서는 요즘 얼음 문 앞에 자주 서 계신다. 문을 열면 남쪽의 불이 들어오고, 닫으면 문 앞까지 온 사람이 얼어 죽는다.\" 그녀가 책을 덮는다. \"두 해 남았다. 그 전에 하나만 묻자. 너는 아직 궁의 사람이냐, 중원의 사람이냐.\"",
 [C("궁의 사람이다",O("하란이 고개를 끄덕였다. \"그럼 답도 궁을 위해 해라.\" 그녀가 궁의 다음 구결을 일러 주었다.",stats={"internal":8,"mind":4},mastery=15,full_growth=True,flags=["빙궁_궁사람"])),
  C("둘 다다",O("하란이 한참 말이 없었다. \"궁주께서 왜 너를 보냈는지 알겠다. 나였으면 그렇게 답하지 못했다.\"",alignment=AL(j=40),stats={"mind":10,"internal":3},full_growth=True,flags=["빙궁_둘다"])),
  C("모르겠다. 그러니 한 수 겨뤄 달라",O("하란이 손을 털며 평상에 도로 앉았다. \"남쪽에서 헛산 것은 아니구나. 손에 불 냄새가 뱄다.\"",battle="북해고수",spar=True,foe_line="\"말로 못 하는 답은 손이 한다. 오너라.\"",stats={"external":6,"martial":6},mastery=15,full_growth=True,flags=["빙궁_겨룸"]))])
story("외전빙궁_끝",o,120,"얼음 문 앞에서",
 "십 년이 찼다. 천 리 빙원 끝, 얼음 문 앞에 궁주 빙백검후 설란이 서 있다. 등 뒤로 궁의 사람들이 늘어섰다. 소궁주 하란이 내 책 열 권을 궁주 앞에 쌓는다. 궁주는 책을 펴지 않는다. \"글은 나중에 읽겠다. 네 입으로 답해라. 문을 열 것인가, 닫을 것인가. 답에는 값이 따른다. 궁의 법이다. 답한 자는 그 답을 제 무공으로 지켜야 한다.\" 하란이 앞으로 나선다.",
 [C("문을 열어야 한다고 답한다",O("하란이 한 걸음 물러섰다. 궁주가 처음으로 책 한 권을 집어 든다.",battle="외전_하란",spar=True,foe_line="\"열자는 답이면, 열고도 궁을 지킬 수 있다는 것부터 보여라.\"",next="개문",lose_next="꺾인답")),
  C("문을 닫아야 한다고 답한다",O("하란이 한 걸음 물러섰다. 궁주가 얼음 문에 손을 얹는다.",battle="외전_하란",spar=True,foe_line="\"닫자는 답이면, 문밖의 원망을 혼자 받아 낼 수 있는지 보여라.\"",next="폐문",lose_next="꺾인답")),
  C("답하지 않고 책만 남긴 채 돌아선다",O("열 권을 얼음 위에 두고 돌아섰다. 아무도 부르지 않았다.",ending="외전빙궁_침묵"))],
 parts={
  "개문":part("궁주가 책장을 넘기며 묻는다. \"열자면 무엇을 위해 여느냐.\"",
   [C("문 앞까지 온 사람을 얼려 죽이지 않기 위해",O("궁주가 책을 덮었다. \"그 답을 들으려고 십 년을 기다렸는지도 모르겠다.\"",ending="외전빙궁_개문")),
    C("남쪽의 판에 궁의 자리를 얻기 위해",O("궁주의 눈썹이 조금 움직였다. \"백 년 동안 아무도 하지 못한 말이다.\"",flags=["빙궁_야심"],ending="외전빙궁_개문"))]),
  "폐문":part("궁주가 얼음 문을 쓸며 묻는다. \"닫자면 언제까지 닫느냐.\"",
   [C("남쪽의 불이 꺼질 때까지",O("궁주가 고개를 끄덕였다. \"백 년 전에도 그렇게 말한 사람이 있었다. 내 스승이다.\"",ending="외전빙궁_폐문")),
    C("영영",O("얼음 문 앞이 조용해졌다. 하란이 나를 돌아보았다.",flags=["빙궁_영영"],ending="외전빙궁_폐문"))]),
  "꺾인답":part("하란의 손바닥이 가슴 앞에서 멈췄다. 답을 무공으로 지키지 못했다. 궁주가 말한다. \"지키지 못한 답은 답이 아니다. 그래도 네가 본 십 년은 남는다.\"",
   [C("책을 올리고 물러난다",O("열 권 위에 눈이 쌓이기 시작했다.",ending="외전빙궁_침묵"))])})
ending("외전빙궁_개문",o,"열린 얼음 문","개문",10,"〈성명:은/는〉 문을 열어야 한다고 답했고, 그 답을 지켜 냈다. 북해빙궁의 얼음 문이 백 년 만에 열렸다.",[
 F(({"flag":"빙궁_야심"},"궁은 문을 열되 어느 편에도 서지 않았다. 다만 그해부터 낙양의 큰 자리마다 흰 옷의 의자가 하나씩 놓였다."),({}, "궁은 문을 열되 어느 편에도 서지 않았다. 빙원을 건너온 사람에게 죽 한 그릇과 털옷 한 벌을 내주었을 뿐이다.")),
 F(({"flag":"빙궁_곤륜"},"처음 문을 넘은 것은 곤륜의 어린 제자 서른이었다. 설봉자는 끝내 오지 않고 편지만 보냈다. 고맙다는 말은 한 줄이었다."),({"flag":"빙궁_밀약"},"곤륜의 어린 제자들이 문을 넘을 때 설봉자가 받아 든 글은 처음 약조와 조금 달랐다. 그는 한참 글을 보다가 접었다."),({}, "남쪽에서 온 아이들은 눈을 처음 보았다.")),
 F(({"flag":"빙궁_북문"},"낙양 북문에서 흰 옷을 본 사람들은 그 문이 왜 열렸는지 묻지 않았다."),({"flag":"빙궁_방관"},"〈그〉의 책 가운데 낙양의 불을 적은 권은 붓이 멈춘 자국이 유난히 많았다. 궁주는 그 권을 가장 오래 읽었다."),({}, "궁주는 책 열 권을 그해 겨울 내내 읽었다.")),
 F(({}, "소궁주 하란은 문지기에게 일렀다. \"누가 열자고 했는지 묻거든 〈성〉 아무개라고 해라. 나는 닫자고 했다가 졌다고.\""))])
ending("외전빙궁_폐문",o,"닫힌 얼음 문","폐문",10,"〈성명:은/는〉 문을 닫아야 한다고 답했고, 그 답을 지켜 냈다. 북해빙궁은 백 년 전처럼 문을 걸었다.",[
 F(({"flag":"빙궁_영영"},"얼음 문 안쪽에 얼음을 한 겹 더 얼렸다. 녹이지 않기로 한 얼음이다."),({}, "문은 닫혔지만 빗장은 안쪽에서 한 뼘만 걸었다. 불이 꺼지면 열기로 한 문이다.")),
 F(({"flag":"빙궁_북문"},"문밖의 원망은 〈그〉가 받았다. 낙양 북문에 섰던 사람이 왜 닫자고 했느냐는 물음에 〈그〉는 답하지 않았다."),({"flag":"빙궁_곤륜"},"곤륜에는 〈그〉가 직접 가서 알렸다. 설봉자는 차 한 잔을 내주고 아무 말도 하지 않았다."),({}, "남쪽의 누구도 그 문을 두드리지 못했다. 두드릴 만큼 가까이 온 사람이 없었다.")),
 F(({}, "궁주는 책 열 권을 서고의 가장 안쪽에 넣었다. \"다음에 누가 문을 열자고 하면 이것부터 읽혀라.\""))])
ending("외전빙궁_침묵",o,"답 없는 열 권","침묵",6,"〈성명:은/는〉 십 년을 보았으나 답을 남기지 못했다. 얼음 위에 책 열 권이 남았다.",[
 F(({"flag":"빙궁_둘다"},"궁의 사람도 중원의 사람도 아닌 채로 〈그〉는 빙원과 관도 사이를 오갔다."),({}, "〈그〉는 빙원을 되짚어 남쪽으로 내려갔다. 털옷은 문 앞에 벗어 두었다.")),
 F(({}, "궁주는 답 대신 남은 책을 끝까지 읽었다. 문을 어찌했는지는 궁 밖에 알려지지 않았다.")),
 F(({}, "소궁주 하란은 해마다 첫눈이 오면 주막 평상에 사람을 보내 빈 책 한 권을 두고 오게 했다."))])
rnd("빙궁_여름",[1,2],"처음 겪는 여름",
 "중원의 여름은 숨이 막힌다. 마을 우물가에 사람들이 늘어져 있다. 가뭄에 우물이 미지근하게 썩어 간다고 한다. 손바닥이 근질거린다. 궁에서는 숨 쉬듯 하던 일이다.",
 [C("우물에 손을 넣어 물을 얼린다",O("우물 위로 흰 김이 올랐다. 아이들이 얼음 조각을 들고 뛰어다녔다. 촌장이 묻는다. \"북쪽 사람은 다 이런가.\" 책에 적었다. '남쪽 사람은 얼음 한 조각에 운다.'",alignment=AL(j=40),stats={"internal":4},fame=10)),
  C("얼음을 만들어 장에 내다 판다",O("한여름의 얼음은 은자와 같은 무게로 팔렸다. 책에 적었다. '남쪽에서는 궁의 겨울이 돈이 된다.'",alignment=AL(s=30),silver=80,stats={"mind":2})),
  C("더위 속에서 일부러 운기한다",O("찬 기운이 더운 숨과 부딪쳐 경맥이 뒤틀렸다. 사흘을 앓고 나니 내력이 한 겹 두꺼워졌다.",stats={"internal":6},hp_pct=-15))],origin=o)
rnd("빙궁_구결",[3,4],"궁에서 온 얼음 조각",
 "궁의 전령이 얼음 조각 하나를 전하고 갔다. 궁의 내력으로 봉한 얼음이라 남쪽의 더위에도 녹지 않았다. 손바닥에 올려 빙심결의 내력을 흘리자 얼음 속에 글자가 떠오르고, 봉한 기운이 풀리기 시작한다. 궁주의 글씨다. '네가 보낸 책을 읽었다. 남쪽에서 싸울 일이 많겠더구나. 이것을 익혀라.'",
 [C("봉한 기운이 다 풀리기 전에 구결을 외운다",O("현빙장의 구결이다. 마지막 구절을 외우자 봉한 기운이 다 풀렸고, 얼음 조각은 그제야 손바닥에서 물이 되었다.",skill="현빙장",stats={"internal":4})),
  C("풀리는 대로 구결을 책에 옮겨 적고 익힌다",O("궁의 구결을 종이에 적는 것은 법에 어긋난다. 그래도 적었다. 붓이 마지막 구절에 닿을 때 얼음은 물이 되었다. 십 년 치의 책에는 궁의 것도 들어 있어야 한다. 현빙장이다.",skill="현빙장",stats={"mind":4}))],origin=o,req={"no_skill":"현빙장"})

enemy("외전_하란","북해고수",hp=46000,attack=410,armor=22,level=97,hp_style=1.366,attack_style=1.19,name="설령수 하란",title="북해빙궁 소궁주",desc="얼음 문 앞에서 궁의 법을 맡은 소궁주. 궁에 답을 올린 자가 그 답을 지킬 만한지 손으로 잰다.",
 intro="\"답은 들었다. 이제 그 답의 무게를 보자.\"",outro="하란의 몸에서 서리가 걷혔다. \"되었다. 네 답이 내 손보다 무겁다.\"",spar_outro="하란이 손을 거두고 한 걸음 물러섰다. \"되었다. 네 답이 내 손보다 무겁다.\"",
 specials=[{"name":"빙백신장","every":3,"mult":2.0,"qi_drain":25},{"name":"설령","every":5,"mult":1.5,"seal":1}],
 phases=[{"hp_pct":50,"attack_mult":1.2,"text":"하란이 얼음 문에 등을 댄다. 문의 냉기가 그녀의 두 손으로 흘러든다.","quirks":[{"type":"barrier","percent":4,"every":5,"name":"얼음 문의 냉기"}]}])
